import type { Checkpoint } from '../contract/types.ts';

export type LocalLeg = 'enforce' | 'evidence';

export interface LocalToolCall {
  name: string;
  server?: string;
  qualified: string;
  source_name: string;
  arguments?: Record<string, unknown>;
  arguments_raw?: string;
  arguments_truncated?: true;
  result?: unknown;
  phase: 'request' | 'response';
  entry_path: 'hooks';
}

export interface LocalPolicyInput {
  trace: {
    id: string;
    name: string;
    metadata: Record<string, unknown>;
    tags: string[];
    input?: string;
    output?: string;
    observations: Record<string, unknown>[];
  };
  tool_call: LocalToolCall;
  tool_calls: LocalToolCall[];
  eval_context: 'hooks';
  phase: Checkpoint;
}

export interface LocalCallFacts {
  /** The normalized dotted name that the mod sends as `tool`. */
  tool: string;
  sessionId: string;
  /** The harness literal that the mod sends as `agent_name`. */
  agentName: string;
  /** The `ai_app_id` that the mod sends. */
  aiAppId: string;
  /** The `user_id` that the mod sends in the verdict request. Absent or empty: the server writes `unknown`. */
  userId?: string | null;
  leg: LocalLeg;
  /** `content.args` of the enforce leg, or `content.output` of the evidence leg: the text that the mod sends. */
  text: string;
  /** Lengths at which the server knows that a source cuts the arguments: HOOKS_SERVER_CONTENT_LIMIT, then the scan window of the tenant. */
  truncationLimits: readonly number[];
}

/** HOOKS_SERVER_CONTENT_LIMIT of server/services/policy/tool-call-input.ts. */
export const HOOKS_SERVER_CONTENT_LIMIT = 100_000;

const ALIAS_SHAPE = /^t_[a-z0-9]+(?:_[a-z0-9]+)+$/;
const ALIAS_SEGMENT_BODY = 't_[a-z0-9]+(?:_[a-z0-9]+)+';
const LITELLM_ALIAS_SEGMENT = new RegExp(`(^|\\.)${ALIAS_SEGMENT_BODY}[-.]`, 'g');
const ALIAS_HINT = /(^|[^A-Za-z0-9])t_[a-z0-9]+_[a-z0-9]/;
const SERVER_ALIAS_TOKEN = /(^|[^A-Za-z0-9])t_[a-z0-9]+(?:_[a-z0-9]+)+(?![A-Za-z0-9])/;
const ALIAS_SEPARATOR = '-';

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function decodeJsonText(text: string): { ok: true; value: unknown } | { ok: false } {
  let value: unknown;
  try {
    value = JSON.parse(text);
  } catch {
    return { ok: false };
  }
  if (typeof value === 'string') {
    try {
      return { ok: true, value: JSON.parse(value) };
    } catch {
      return { ok: true, value };
    }
  }
  return { ok: true, value };
}

function parseToolResult(raw: string): unknown {
  const parsed = decodeJsonText(raw);
  return parsed.ok && parsed.value !== null ? parsed.value : raw;
}

function parseToolArguments(raw: string, truncationLimits: readonly number[]): Pick<LocalToolCall, 'arguments' | 'arguments_raw' | 'arguments_truncated'> {
  if (raw === '') return {};
  const parsed = decodeJsonText(raw);
  if (parsed.ok && isPlainObject(parsed.value)) return { arguments: parsed.value };
  return {
    arguments_raw: raw,
    ...(!parsed.ok && truncationLimits.includes(raw.length) ? { arguments_truncated: true as const } : {}),
  };
}

// The alias guards of tool-call-input.ts (removeAliases, aliasFree), for the tenant whose alias index is complete
// and empty: no registered alias and no tenant token. Each pattern is a copy of the pattern with the same name there.
const ALIAS_WORD = new RegExp(`(^|\\s)${ALIAS_SEGMENT_BODY}(?:\\s+|$)`, 'g');
const BOUNDED_ALIAS_TOKEN = new RegExp(`(^|[^A-Za-z0-9_])${ALIAS_SEGMENT_BODY}(?![A-Za-z0-9])`, 'g');
const BROKERED_ALIAS_SEGMENT = new RegExp(
  `(^|[^A-Za-z0-9_])(mcp__)${ALIAS_SEGMENT_BODY}(?:(__)(?=[A-Za-z0-9])|(?![A-Za-z0-9_]))`,
  'g',
);
const NAMESPACE_TENANT_TOKEN = '(?=[0-9a-f]{0,11}[0-9])(?=[0-9a-f]{0,11}[a-f])[0-9a-f]{12}';
const NAMESPACE_ALIAS_PREFIX = new RegExp(`(^|[^A-Za-z0-9])t_${NAMESPACE_TENANT_TOKEN}_(?=[a-z0-9])`, 'g');

/** ALIAS_ONLY_TOOL_NAME of tool-call-input.ts. */
const ALIAS_ONLY_TOOL_NAME = 'unknown_tool';

function replaceUntilStable(text: string, pattern: RegExp): string {
  let out = text;
  for (let prev = ''; prev !== out; ) {
    prev = out;
    out = out.replace(pattern, '$1');
  }
  return out;
}

function removeAliases(text: string): string {
  let out = replaceUntilStable(text, LITELLM_ALIAS_SEGMENT);
  if (ALIAS_HINT.test(out)) out = replaceUntilStable(out, NAMESPACE_ALIAS_PREFIX);
  out = out.replace(
    BROKERED_ALIAS_SEGMENT,
    (_match: string, before: string, prefix: string, toolSeparator: string | undefined) =>
      toolSeparator ? `${before}${prefix}` : `${before}${prefix}${ALIAS_ONLY_TOOL_NAME}`,
  );
  const withoutWords = replaceUntilStable(out, ALIAS_WORD);
  if (withoutWords !== out) out = withoutWords.replace(/\s+$/, '');
  out = out.replace(
    BOUNDED_ALIAS_TOKEN,
    (match: string, before: string, offset: number, whole: string) =>
      before !== '' && offset + match.length === whole.length ? `${before}${ALIAS_ONLY_TOOL_NAME}` : before,
  );
  out = replaceUntilStable(out, BOUNDED_ALIAS_TOKEN);
  return ALIAS_SHAPE.test(out) ? '' : out;
}

/** aliasFree of tool-call-input.ts: a text that is wholly an alias of no registered server becomes the unknown-tool name. */
function aliasFree(text: string): string {
  const out = removeAliases(text);
  return out !== '' || text === '' ? out : ALIAS_ONLY_TOOL_NAME;
}

function serverFromValue(value: string | undefined): string | undefined {
  const text = value?.trim();
  if (!text) return undefined;
  if (SERVER_ALIAS_TOKEN.test(text)) return undefined;
  if (removeAliases(text) !== text) return undefined;
  return text;
}

/** hooksToolMayCarryGatewayName of tool-call-input.ts: a name for which the alias index of the server can matter. */
export function toolMayCarryGatewayName(tool: string): boolean {
  return tool !== '' && (ALIAS_HINT.test(tool) || tool.includes(ALIAS_SEPARATOR));
}

/** buildHooksToolCall of tool-call-input.ts, for a tenant without gateway aliases. */
export function localToolCall(facts: Pick<LocalCallFacts, 'tool' | 'leg' | 'text' | 'truncationLimits'>): LocalToolCall {
  const { tool } = facts;
  const dot = tool.indexOf('.');
  const configKey = dot > 0 && dot < tool.length - 1 ? tool.slice(0, dot) : undefined;
  const toolPart = configKey !== undefined ? tool.slice(dot + 1) : tool;
  const name = aliasFree(toolPart);
  const server = serverFromValue(configKey);
  const sourceName = removeAliases(tool) || name;
  const enforce = facts.leg === 'enforce';
  return {
    name,
    ...(server ? { server } : {}),
    qualified: server ? `${server}.${name}` : name,
    source_name: sourceName,
    // The mod sends `args` on the enforce leg and `output` on the evidence leg, never both.
    ...(enforce ? parseToolArguments(facts.text, facts.truncationLimits) : {}),
    ...(!enforce && facts.text !== '' ? { result: parseToolResult(facts.text) } : {}),
    phase: enforce ? 'request' : 'response',
    entry_path: 'hooks',
  };
}

/** buildDecisionTrace (hooks branch) of decision-core.ts, with the identity that the mod sends. */
export function localPolicyInput(facts: LocalCallFacts): LocalPolicyInput {
  const { tool, sessionId, agentName, aiAppId, leg, text } = facts;
  const userId = facts.userId || 'unknown';
  const enforce = leg === 'enforce';
  const content = text === '' ? {} : enforce ? { input: text } : { output: text };
  const call = localToolCall(facts);
  return {
    trace: {
      id: `arbiter:${sessionId}:${tool}:0`,
      name: tool,
      metadata: {
        tool_name: tool,
        tool_calls: [{ name: tool, arguments: enforce && text !== '' ? text : {} }],
        tools_called: [tool],
        tools_used: [tool],
        arbiter_evaluation: true,
        agent_name: agentName,
        user_id: userId,
        ai_app_id: aiAppId,
        registered: true,
        attributes: { 'gen_ai.agent.name': agentName, 'gen_ai.agent.user.id': userId },
      },
      tags: ['arbiter'],
      ...content,
      observations: [
        {
          id: `arbiter:${sessionId}:${tool}:obs`,
          type: 'TOOL',
          name: tool,
          metadata: { session_id: sessionId },
          ...content,
        },
      ],
    },
    tool_call: call,
    tool_calls: [call],
    eval_context: 'hooks',
    phase: enforce ? 'tool_call_input' : 'tool_call_output',
  };
}

/** The JSON that the server sends to OPA: `dropNullJsonReplacer` of opa-client.ts, which makes a null key the same as an absent key. */
export function dropNulls(value: unknown): unknown {
  return JSON.parse(JSON.stringify(value, (_key, v: unknown) => (v === null ? undefined : v)) ?? 'null');
}
